    try:
        m=json.load(urllib.request.urlopen('https://jaspar.elixir.no/api/v1/matrix/'+id+'/',timeout=10))
        print(id,m.get('name'),m.get('collection'),m.get('tax_id'),m.get('tax_group'),m.get('species'))
    except Exception as e: print(id,e)
PY"

