/bin/bash -lc "python3 - <<'PY'
import urllib.request, json, urllib.parse
base='https://jaspar.elixir.no/api/v1/matrix/?collection=CORE&format=json&page_size=1000&page='
all=[]
for page in [1,2,3,4,5]:
    url=base+str(page)
    try:
        data=json.load(urllib.request.urlopen(url,timeout=30))
        print(page,len(data['results']))
        all+=data['results']
        if not data['next']:
            print('no next at',page); break
    except Exception as e:
        print(e); break
print('total',len(all))
# save list ids names
for m in all:
    pass
# filter exact normalized names
names=['FOXA1','GATA3','MAX','STAT1','POU5F1','TP53','NANOG','HNF4A','TBP','FOS','MYC','JUN','FOXO1','CTCF','TCF7','SOX2','E2F1','CREB1','GATA1','KLF3']
for n in names:
    print('\\n',n)
    for m in all:
        if m['name'].upper()==n.upper():
            print(m['matrix_id'],m['name'],m.get('tax_id'))
PY"

